"""Tests para el endpoint de obtener transaccion por ID."""

from app.main import app
from fastapi.testclient import TestClient
from tests.test_auth import get_token

client = TestClient(app)


def test_get_transaccion():
    """Test para obtener una transaccion por su ID."""

    token = get_token()
    body = {"id_recurso": "PC-1"}

    response = client.post(
        "/transaccion/", headers={"Authorization": f"Bearer {token}"}, json=body
    )

    assert response.status_code == 200
    assert response.json() == [
        {
            "transaccion": 1,
            "estado_actual": {
                "id_estado_transaccion": 4,
                "nombre_estado_transaccion": "Completada",
            },
            "fechas": {
                "fecha_inicio_transaccion": "2025-11-23T09:00:00",
                "fecha_fin_transaccion": "2025-11-23T12:00:00",
                "fecha_creacion": "2025-12-09T19:27:52.058260",
            },
            "recurso": {
                "id_recurso": "PC-1",
                "nombre_recurso": "Lenovo 420",
                "foto_recurso": "",
            },
            "usuario": {"id_usuario": 2, "nombre": "Laura", "apellido": "Ramírez"},
            "empleado_responsable": {
                "id_usuario": 7,
                "nombre": "Julián",
                "apellido": "Cortés",
            },
            "falla_servicio": None,
        }
    ]


def test_post_transaccion():
    """Test para crear una transaccion."""

    token = get_token(3)

    body = {
        "fecha_inicio_transaccion": "2025-12-10T21:34:20.369Z",
        "fecha_fin_transaccion": "2025-12-10T23:34:20.369Z",
        "id_recurso": "PC-1",
    }

    response = client.post(
        "/transaccion/create",
        headers={"Authorization": f"Bearer {token}"},
        json=body,
    )
    assert response.status_code == 201
